const headerAlias={lesson:'lesson','lesson name':'lesson',name:'name',korean:'korean','korean word':'korean',word:'korean',term:'korean',pos:'pos','part of speech':'pos',meaning:'meaning','english meaning':'meaning',definition:'meaning',origin:'origin','word origin':'origin',etymology:'origin',example:'example','example sentence':'example',examples:'example',image:'image','image url':'image',pattern:'pattern','grammar pattern':'pattern',grammar:'pattern',explain:'explain',explanation:'explain','grammar explanation':'explain'};
function cleanHeader(h){h=String(h||'').replace(/^\ufeff/,'').trim().toLowerCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ');return headerAlias[h]||h}
function normalizeCsvUrl(url){url=String(url||'').trim();if(!url)return '';try{if(url.includes('/pubhtml'))url=url.replace('/pubhtml','/pub');if(url.includes('/pub?')){const u=new URL(url);u.searchParams.set('single','true');u.searchParams.set('output','csv');return u.toString()}}catch{}return url}
async function fetchCsv(url,label){const res=await fetch(normalizeCsvUrl(url),{cache:'no-store'});if(!res.ok)throw new Error(`${label}: HTTP ${res.status}`);const text=await res.text();const parsed=Papa.parse(text,{header:true,skipEmptyLines:'greedy',transformHeader:cleanHeader});return parsed.data.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[cleanHeader(k),String(v??'').trim()]))) }
async function fetchJson(path){const r=await fetch(`${path}?ts=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`${path}: HTTP ${r.status}`);return r.json()}

async function loadContent(){
  document.getElementById('syncStatus').textContent='Loading course content…';loadStats={sheet:0,repo:0,course:0,errors:[]};
  const [courseRes,repoRes,lessonIndexRes,verificationRes,conceptRes,systemRes,crosswalkRes]=await Promise.allSettled([fetchJson('content/lesson13.json'),fetchJson('shared-content.json'),fetchJson('content/lessons-v1/index.json'),fetchJson('content/enrichment-verification-v1.json'),fetchJson('content/concept-registry-v1.json'),fetchJson('content/system-map-v1.json'),fetchJson('content/concept-crosswalk-v1.json')]);
  coursePack=courseRes.status==='fulfilled'?courseRes.value:null;if(!coursePack)loadStats.errors.push('Lesson 13 pack failed to load');
  repoPack=repoRes.status==='fulfilled'?repoRes.value:{lessons:[],vocab:[],grammar:[]};
  lessonPackIndex=lessonIndexRes.status==='fulfilled'?lessonIndexRes.value:null;if(!lessonPackIndex)loadStats.errors.push('Lesson 1-14 index failed to load');
  verificationRegister=verificationRes.status==='fulfilled'?verificationRes.value:null;if(!verificationRegister)loadStats.errors.push('Enrichment verification register failed to load');
  conceptRegistry=conceptRes.status==='fulfilled'?conceptRes.value:null;
  systemMap=systemRes.status==='fulfilled'?systemRes.value:null;
  conceptCrosswalk=crosswalkRes.status==='fulfilled'?crosswalkRes.value:null;
  verificationKeys=new Set((verificationRegister?.verifiedItems||[]).map(item=>`${item.lessonId}::${item.itemId}`));
  const lessonPackFiles=(lessonPackIndex?.packs||[]).map(p=>`content/lessons-v1/${p.file}`);
  if(lessonPackFiles.length){
    const packResults=await Promise.allSettled(lessonPackFiles.map(file=>fetchJson(file)));
    coursePacks=packResults.filter(r=>r.status==='fulfilled').map(r=>r.value);
    const failed=packResults.filter(r=>r.status==='rejected').length;if(failed)loadStats.errors.push(`${failed} structured lesson pack${failed===1?'':'s'} failed to load`);
  }else coursePacks=[];
  const urls={lessons:config.lessons||config.lessonsUrl||DEFAULT_CONFIG.lessons,vocab:config.vocab||config.vocabUrl||DEFAULT_CONFIG.vocab,grammar:config.grammar||config.grammarUrl||DEFAULT_CONFIG.grammar};config=urls;writeJSON(KEYS.config,config);
  const res=await Promise.allSettled([fetchCsv(urls.lessons,'Lessons'),fetchCsv(urls.vocab,'Vocabulary'),fetchCsv(urls.grammar,'Grammar')]);
  const L=res[0].status==='fulfilled'?res[0].value:(loadStats.errors.push(res[0].reason.message),[]);const V=res[1].status==='fulfilled'?res[1].value:(loadStats.errors.push(res[1].reason.message),[]);const G=res[2].status==='fulfilled'?res[2].value:(loadStats.errors.push(res[2].reason.message),[]);
  shared.lessons=L.filter(r=>r.name||r.lesson).map(r=>{const name=r.name||r.lesson;return{id:lessonKey(name),name,shared:true,source:'sheet'}});
  shared.vocab=V.filter(r=>r.korean).map(r=>({id:'sv-'+lessonKey(r.lesson)+'-'+lessonKey(r.korean),lessonId:lessonKey(r.lesson),lessonName:r.lesson||'Unsorted',korean:r.korean,pos:r.pos||'',meaning:r.meaning||'',origin:r.origin||'',example:r.example||'',image:r.image||'',shared:true,source:'sheet'}));
  shared.grammar=G.filter(r=>r.pattern).map(r=>({id:'sg-'+lessonKey(r.lesson)+'-'+lessonKey(r.pattern),lessonId:lessonKey(r.lesson),lessonName:r.lesson||'Unsorted',pattern:r.pattern,explain:r.explain||'',example:r.example||'',shared:true,source:'sheet'}));
  loadStats.sheet=shared.vocab.length+shared.grammar.length;loadStats.repo=(repoPack.vocab||[]).length+(repoPack.grammar||[]).length;loadStats.course=coursePack?(coursePack.vocabulary.length+coursePack.grammar.length):0;loadStats.lessonPacks=coursePacks.length;loadStats.verified=(verificationRegister?.verifiedItems||[]).length;
  merge();if(!allLessons.some(l=>l.id===currentLesson))currentLesson=allLessons[0]?.id||'all';renderAll();
}
function normalizeRepo(){const lessons=(repoPack.lessons||[]).map(l=>typeof l==='string'?{name:l}:l).filter(l=>l.name).map(l=>({id:l.id||lessonKey(l.name),name:l.name,shared:true,source:'repo'}));const vocab=(repoPack.vocab||[]).filter(v=>v.korean).map(v=>({id:v.id||'rv-'+lessonKey(v.lesson||v.lessonName)+'-'+lessonKey(v.korean),lessonId:v.lessonId||lessonKey(v.lesson||v.lessonName),lessonName:v.lesson||v.lessonName||'Unsorted',korean:v.korean,pos:v.pos||'',meaning:v.meaning||'',origin:v.origin||'',example:Array.isArray(v.example)?v.example.join('\n'):(v.example||''),image:v.image||'',shared:true,source:'repo'}));const grammar=(repoPack.grammar||[]).filter(g=>g.pattern).map(g=>({id:g.id||'rg-'+lessonKey(g.lesson||g.lessonName)+'-'+lessonKey(g.pattern),lessonId:g.lessonId||lessonKey(g.lesson||g.lessonName),lessonName:g.lesson||g.lessonName||'Unsorted',pattern:g.pattern,explain:g.explain||g.explanation||'',example:Array.isArray(g.example)?g.example.join('\n'):(g.example||''),shared:true,source:'repo'}));return{lessons,vocab,grammar}}
function normalizeCourse(){if(!coursePack)return{lessons:[],vocab:[],grammar:[]};const l=coursePack.lesson;return{lessons:[{id:l.id,name:l.name,shared:true,source:'course'}],vocab:coursePack.vocabulary.map(v=>({id:'cv-'+lessonKey(v.korean),lessonId:l.id,lessonName:l.name,korean:v.korean,meaning:v.meaning,pos:v.group||'',origin:'',example:'',group:v.group||'',shared:true,source:'course'})),grammar:coursePack.grammar.map(g=>({id:g.id,lessonId:l.id,lessonName:l.name,pattern:g.pattern,explain:g.explain,example:(g.examples||[]).join('\n'),code:g.code,title:g.title,formula:g.formula,contrast:g.contrast,pitfall:g.pitfall,shared:true,source:'course'}))}}
function lessonPackName(pack){const l=pack.lesson||{};return `Lesson ${l.number||String(l.id||'').replace(/\D/g,'')}: ${l.titleKo||l.name||'Untitled'}${l.titleEn?` · ${l.titleEn}`:''}`}
