function verifiedItem(lessonId,itemId){return verificationKeys.has(`${lessonId}::${itemId}`)}
function formatExample(ex){if(!ex)return'';if(typeof ex==='string')return ex;return [ex.ko,ex.en].filter(Boolean).join(' — ')}
function normalizeLessonPacks(){const lessons=[],vocab=[],grammar=[];coursePacks.forEach(pack=>{const l=pack.lesson||{},lessonId=l.id||lessonKey(l.titleEn||l.titleKo||'lesson'),lessonName=lessonPackName(pack);lessons.push({id:lessonId,name:lessonName,shared:true,source:'lessons-v1',number:l.number||999});(pack.vocabulary||[]).forEach(v=>vocab.push({id:v.id||`lv-${lessonId}-${lessonKey(v.korean)}`,lessonId,lessonName,korean:v.korean,meaning:v.meaningEn||v.meaning||'',meaningZh:v.meaningZh||'',pos:v.pos||'',origin:[v.hanja,v.originType].filter(Boolean).join(' · '),hanja:v.hanja||'',originType:v.originType||'',originNote:v.originNote||'',example:'',tags:v.tags||[],verified:verifiedItem(lessonId,v.id),shared:true,source:'lessons-v1'}));(pack.grammar||[]).forEach(g=>grammar.push({id:g.id||`lg-${lessonId}-${lessonKey(g.pattern)}`,lessonId,lessonName,pattern:g.pattern,name:g.name||'',title:g.name||g.title||'',explain:g.meaning||g.explain||'',example:(g.examples||[]).map(formatExample).filter(Boolean).join('\n'),examples:(g.examples||[]).map(formatExample).filter(Boolean),formula:(g.formation||[]).join('\n'),contrast:(g.contrast||[]).map(c=>`${c.with}: ${c.note}`).join('\n'),pitfall:(g.commonMistakes||[]).join('\n'),tags:g.tags||[],shared:true,source:'lessons-v1'}))});return{lessons,vocab,grammar}}
function merge(){const rp=normalizeRepo(),cp=normalizeCourse(),lp=normalizeLessonPacks();const lessonMap=new Map();[...rp.lessons,...shared.lessons,...cp.lessons,...lp.lessons,...local.lessons].forEach(l=>lessonMap.set(l.id,l));const dedupe=(arr,keyFn)=>{const m=new Map();arr.forEach(x=>m.set(keyFn(x),x));return [...m.values()]};allVocab=dedupe([...shared.vocab,...rp.vocab,...cp.vocab,...lp.vocab,...local.vocab],v=>`${v.lessonId}::${v.korean}`);allGrammar=dedupe([...shared.grammar,...rp.grammar,...cp.grammar,...lp.grammar,...local.grammar],g=>`${g.lessonId}::${g.pattern}`);[...allVocab,...allGrammar].forEach(x=>{if(!lessonMap.has(x.lessonId))lessonMap.set(x.lessonId,{id:x.lessonId,name:x.lessonName||'Unsorted',shared:true})});allLessons=[...lessonMap.values()].sort((a,b)=>{const na=a.number||+(a.name.match(/\d+/)||[999])[0],nb=b.number||+(b.name.match(/\d+/)||[999])[0];return na-nb||a.name.localeCompare(b.name)})}

function currentPool(){return{vocab:allVocab.filter(v=>currentLesson==='all'||v.lessonId===currentLesson),grammar:allGrammar.filter(g=>currentLesson==='all'||g.lessonId===currentLesson)}}
function isFav(id){return local.favorites.includes(id)}
function toggleFav(id){local.favorites=isFav(id)?local.favorites.filter(x=>x!==id):[...local.favorites,id];writeJSON(KEYS.local,local);renderCurrent()}
function progressFor(id){return local.progress[id]||{reps:0,interval:0,ease:2.5,due:today()}}
