function logActivity(kind){local.activity.push({date:today(),kind,ts:Date.now()});local.activity=local.activity.slice(-300);writeJSON(KEYS.local,local);renderStreak()}
function renderStreak(){const days=[...new Set(local.activity.map(x=>x.date))].sort().reverse();let streak=0,d=new Date();for(let i=0;i<60;i++){const s=d.toISOString().slice(0,10);if(days.includes(s)){streak++;d.setDate(d.getDate()-1)}else if(i===0){d.setDate(d.getDate()-1)}else break}document.getElementById('streakBadge').textContent=`${streak} day${streak===1?'':'s'} streak`}

