const viewTitles={today:['Today','A small plan for your next Korean study session.'],lesson:['Lesson','See the structure of the lesson before drilling details.'],browse:['Browse','Search, compare, save, and hear what matters.'],practice:['Practice','Recall first, then use feedback to fix the reason you missed it.'],review:['Flashcards','Review with progressively longer intervals.'],quiz:['Quiz','A short mixed check of what you can retrieve.'],mistakes:['Mistakes','Turn errors into a targeted review list.'],basics:['Beginner','Build the foundations before memorizing details.'],qa:['Content QA','Teacher-source lesson packs and verified enrichment are separated here.'],explore:['Explore','Cross-lesson Korean systems and concept maps.']};
function switchView(view){currentView=view;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.view===view));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));const title=viewTitles[view]||viewTitles.today;document.getElementById('pageTitle').textContent=title[0];document.getElementById('pageSubtitle').textContent=title[1];renderCurrent()}
function renderCurrent(){if(currentView==='today')renderToday();if(currentView==='lesson')renderLesson();if(currentView==='browse')renderBrowse();if(currentView==='practice')renderPractice();if(currentView==='review')renderReview();if(currentView==='quiz')renderQuiz();if(currentView==='mistakes')renderMistakes();if(currentView==='basics')renderBasics();if(currentView==='qa')renderQa()}
